class Solution {
public:
    vector<int> findOriginalArray(vector<int>& changed) {
        int n=changed.size();
        vector<int> ans;
        map<int,int> mp;
        for(auto it:changed)
            mp[it]+=1;
        if(n%2!=0)
            return ans;
        sort(changed.begin(),changed.end());
        for(int i=0;i<n;i++)
        {
            if(mp[changed[i]]==0)
                continue;
            if(mp[changed[i]*2]==0)
                return {};
            ans.push_back(changed[i]);
            mp[changed[i]]-=1;
            mp[changed[i]*2]-=1;
        }
        return ans;
    }
};

class Solution(object):
    def findOriginalArray(self, changed):
        """
        :type changed: List[int]
        :rtype: List[int]
        """
        n = len(changed)
        changed.sort()
        ans = []
        info = collections.defaultdict(int)
        for num in changed:
            if info[num] == 0:
                ans.append(num)
                info[num * 2] += 1
            else:
                info[num] -= 1
        for k, v in info.items():
            if v != 0:
                return []
        return ans
